package com.bank.producer.config;

import org.apache.kafka.clients.admin.NewTopic;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.config.TopicBuilder;

@Configuration
public class KafkaProducerConfig {

    @Bean
    NewTopic tradeEventsTopic(
            @Value("${kafka.topics.trade-events.name}") String name,
            @Value("${kafka.topics.trade-events.partitions}") int partitions,
            @Value("${kafka.topics.trade-events.replicas}") int replicas) {
        return TopicBuilder.name(name)
            .partitions(partitions)   // 6 partitions = up to 6 parallel consumers
            .replicas(replicas)
            .build();
    }
}
