package com.bank.producer.service;

import com.bank.producer.model.TradeEvent;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradeEventProducer {

    private final KafkaTemplate<String, TradeEvent> kafkaTemplate;

    /**
     * KEY = accountId: all events for same account go to SAME partition.
     * This guarantees ORDER within one account (partition ordering).
     */
    public void publishTradeEvent(TradeEvent event) {
        kafkaTemplate.send("trade-events", event.accountId(), event)
            .whenComplete((result, ex) -> {
                if (ex != null) {
                    log.error("Failed to publish trade event {}: {}", event.tradeId(), ex.getMessage());
                } else {
                    log.info("Published: {} to partition {} offset {}",
                        event.tradeId(),
                        result.getRecordMetadata().partition(),
                        result.getRecordMetadata().offset());
                }
            });
    }
}
