package com.bank.producer.controller;

import com.bank.producer.model.TradeEvent;
import com.bank.producer.service.TradeEventProducer;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@RestController
@RequestMapping("/api/v1/trades")
@RequiredArgsConstructor
public class TradePublishController {

    private final TradeEventProducer producer;

    @PostMapping("/publish")
    public String publish(@RequestParam String accountId,
                           @RequestParam String symbol,
                           @RequestParam String side,
                           @RequestParam int quantity,
                           @RequestParam BigDecimal price) {
        String tradeId = "TRD-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        BigDecimal total = price.multiply(BigDecimal.valueOf(quantity));

        TradeEvent event = new TradeEvent(tradeId, accountId, symbol, side,
            quantity, price, total, LocalDateTime.now());
        producer.publishTradeEvent(event);
        return "Published: " + tradeId;
    }
}
