package com.bank.consumer.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "settlements")
public class Settlement {

    @Id
    @Column(name = "settlement_id")
    private String settlementId;

    @Column(name = "trade_id", nullable = false, unique = true)
    private String tradeId;   // UNIQUE: idempotency — duplicate Kafka events safely ignored

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(nullable = false)
    private String symbol;

    @Column(nullable = false)
    private BigDecimal amount;

    @Column(nullable = false)
    private String status;

    @Column(name = "kafka_offset")
    private Long kafkaOffset;

    @Column(name = "kafka_partition")
    private Integer kafkaPartition;

    @Column(name = "created_at")
    private LocalDateTime createdAt;

    protected Settlement() {}

    public Settlement(String settlementId, String tradeId, String accountId,
                       String symbol, BigDecimal amount, long offset, int partition) {
        this.settlementId = settlementId;
        this.tradeId = tradeId;
        this.accountId = accountId;
        this.symbol = symbol;
        this.amount = amount;
        this.status = "SETTLED";
        this.kafkaOffset = offset;
        this.kafkaPartition = partition;
        this.createdAt = LocalDateTime.now();
    }

    public String getTradeId() { return tradeId; }
}
