package com.bank.consumer.service;

import com.bank.consumer.model.Settlement;
import com.bank.consumer.repository.SettlementRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class SettlementService {

    private final SettlementRepository settlementRepo;

    @Transactional
    public void settle(String tradeId, String accountId, String symbol,
                        BigDecimal amount, long offset, int partition) {
        // IDEMPOTENCY: check if already processed (UNIQUE constraint on trade_id)
        if (settlementRepo.existsByTradeId(tradeId)) {
            log.warn("DUPLICATE: trade {} already settled — skipping (at-least-once is safe)", tradeId);
            return;
        }

        String settlementId = "STL-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        Settlement settlement = new Settlement(settlementId, tradeId, accountId,
            symbol, amount, offset, partition);
        settlementRepo.save(settlement);

        log.info("Settled: {} → {} (partition={}, offset={})", tradeId, settlementId, partition, offset);
    }
}
