// @RetryableTopic: auto-retry failed messages with backoff, then DLT
package com.bank.consumer.listener;

import com.bank.consumer.service.SettlementService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.annotation.RetryableTopic;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.retry.annotation.Backoff;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;
import java.util.Map;

@Component
@RequiredArgsConstructor
@Slf4j
public class SettlementListener {

    private final SettlementService settlementService;

    /**
     * @RetryableTopic: Spring Kafka creates retry topics automatically:
     *   trade-events → trade-events-retry-0 → trade-events-retry-1 → trade-events-dlt
     * Failed message moves through retry topics with backoff, then to DLT.
     */
    @RetryableTopic(
        attempts = "3",
        backoff = @Backoff(delay = 1000, multiplier = 2),  // 1s, 2s, 4s
        dltTopicSuffix = "-dlt")
    @KafkaListener(topics = "trade-events", groupId = "settlement-group",
                    concurrency = "3")  // 3 consumer threads (max = partition count)
    public void onTradeEvent(ConsumerRecord<String, Map<String, Object>> record,
                              Acknowledgment ack) {
        Map<String, Object> event = record.value();
        String tradeId = (String) event.get("tradeId");
        String accountId = (String) event.get("accountId");
        String symbol = (String) event.get("symbol");
        BigDecimal amount = new BigDecimal(event.get("totalAmount").toString());

        log.info("Received: {} from partition={} offset={}",
            tradeId, record.partition(), record.offset());

        settlementService.settle(tradeId, accountId, symbol, amount,
            record.offset(), record.partition());

        ack.acknowledge();  // MANUAL commit — at-least-once (process then commit)
    }
}
