package com.bank.consumer.listener;

import lombok.extern.slf4j.Slf4j;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.kafka.annotation.DltHandler;
import org.springframework.stereotype.Component;

@Component
@Slf4j
public class DltHandler {

    @DltHandler
    public void handleDlt(ConsumerRecord<String, ?> record) {
        log.error("DLT: message FAILED after all retries — manual investigation needed. " +
            "topic={}, partition={}, offset={}, key={}, value={}",
            record.topic(), record.partition(), record.offset(), record.key(), record.value());
        // In production: store to DB, alert ops team, or send to manual processing queue
    }
}
